scriptLabs.solution:
$file = "C:\Downloads\installer.exe"
$expected = "PASTE_PUBLISHED_HASH_HERE"
$actual = (Get-FileHash -Path $file -Algorithm SHA256).Hash
if ($actual -eq $expected) {
    Write-Host "MATCH: download is intact."
} else {
    Write-Host "MISMATCH: do not install - investigate."
}

